import { MeshStandardNodeMaterial } from 'three/webgpu';
import {
  uv,
  color,
  mix,
  smoothstep,
  step,
  texture,
  uniform,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'hub-collection-card-0-label';

  const palette = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const inkColor = color(palette.ink);
  const paperColor = color(palette.paper);
  const accentColor = color(palette.accent);

  // ---- label plate (small machined-metal tag, not the full card) ----
  const width = 1.3;
  const height = 0.5;
  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);

  const material = new MeshStandardNodeMaterial({
    roughness: 0.56,
    metalness: 0.42,
  });

  // engineered vertical gradient: ink -> slightly lifted ink (subtle, no pastel wash)
  const liftedInk = mix(inkColor, paperColor, 0.06);
  const verticalGradient = mix(inkColor, liftedInk, smoothstep(0.0, 1.0, uv().y));

  // thin accent underline at the base of the label (signal red, <=10% of frame)
  const underlineMask = step(uv().y, 0.08);
  const baseColorNode = mix(verticalGradient, accentColor, underlineMask);

  material.colorNode = baseColorNode;
  material.roughnessNode = uniform(0.56);
  material.metalnessNode = uniform(0.42);
  material.clearcoat = 0.18;
  material.clearcoatRoughness = 0.4;

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'label-plate';
  group.add(plane);

  // ---- texture (shared feature-card asset, blended subtly under the tag) ----
  let loadedTexture = null;
  const texPromise = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
        loadedTexture = tex;
        tex.colorSpace = THREE.SRGBColorSpace ?? tex.colorSpace;
        const sampled = texture(tex, uv());
        material.colorNode = mix(baseColorNode, mix(baseColorNode, sampled, 0.22), 1.0);
        material.needsUpdate = true;
      })
    : Promise.resolve();

  // ---- text: "Collection 3" ----
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [
      { text: 'Collection 3', role: 'headline', typography: { fontSize: 39 } },
    ];

  const headlineItem =
    items.find((i) => i.role === 'headline') ?? items[0] ?? { text: 'Collection 3' };

  const label = ctx.fontAtlas.createText(headlineItem.text ?? 'Collection 3', {
    fontSize: headlineItem.typography?.fontSize ?? 39,
    color: palette.paper,
    align: 'center',
    maxWidthPx: 480,
  });
  label.name = 'label-text';
  label.position.set(0, 0.03, 0.02);
  group.add(label);

  // apply scene placement provided
  const pos = config.scenePosition ?? { x: 3.2, y: 1, z: 0.06 };
  group.position.set(pos.x ?? 3.2, pos.y ?? 1, pos.z ?? 0.06);

  // ---- weighted, restrained entrance (no primitives configured for this node) ----
  group.scale.set(0.96, 0.96, 0.96);
  const startY = group.position.y - 0.12;
  const targetY = group.position.y;
  group.position.y = startY;

  const tl = gsap.timeline();
  tl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  tl.to(
    group.position,
    {
      y: targetY,
      duration: 0.7,
      ease: 'power3.out',
    },
    0
  );

  group.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(group.position);

    geometry.dispose();
    material.dispose();
    if (loadedTexture) {
      loadedTexture.dispose();
    }

    if (label?.geometry) label.geometry.dispose?.();
    if (label?.material) label.material.dispose?.();

    group.remove(plane);
    group.remove(label);
  };

  group.userData.handlers = {};

  return group;
}
